import * as React from "react";

import { cn } from "../lib/utils";
import { Icon, type IconSource } from "./icon";
import { Spinner } from "./spinner";

import styles from "./text.module.css";

type TextProps = React.ComponentPropsWithoutRef<"p"> & {
  muted?: boolean;
  /** Keeps the line breaks and spaces in user-entered text, such as notes, and still wraps long lines. */
  preWrap?: boolean;
} & { ref?: React.Ref<HTMLParagraphElement> };

export function Text({ muted = false, preWrap = false, className, ref, ...props }: TextProps) {
  return (
    <p
      ref={ref}
      data-slot="text"
      className={cn(styles.text, muted && styles.muted, preWrap && styles.preWrap, className)}
      {...props}
    />
  );
}
Text.displayName = "Text";
export function SmallText({ muted = false, preWrap = false, className, ref, ...props }: TextProps) {
  return (
    <p
      ref={ref}
      data-slot="small-text"
      className={cn(styles.small, muted && styles.muted, preWrap && styles.preWrap, className)}
      {...props}
    />
  );
}
SmallText.displayName = "SmallText";

export function Heading({
  level = 2,
  size = "section",
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"h2"> & {
  level?: 1 | 2 | 3 | 4 | 5 | 6;
  size?: "page" | "display" | "section" | "subsection";
} & { ref?: React.Ref<HTMLHeadingElement> }) {
  const Tag: "h1" | "h2" | "h3" | "h4" | "h5" | "h6" = `h${level}`;
  return (
    <Tag
      ref={ref}
      data-slot="heading"
      data-size={size}
      className={cn(styles.heading, className)}
      {...props}
    />
  );
}
Heading.displayName = "Heading";
export function Meta({
  mono = true,
  className,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"span"> & { mono?: boolean } & {
  ref?: React.Ref<HTMLSpanElement>;
}) {
  return (
    <span
      ref={ref}
      data-slot="meta"
      className={cn(styles.meta, mono && styles.mono, className)}
      {...props}
    />
  );
}
Meta.displayName = "Meta";

export function StatusText({
  tone = "neutral",
  size,
  icon,
  loading = false,
  className,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"span"> & {
  tone?: "neutral" | "ok" | "warn" | "bad";
  /** sm sets small text and md body text; without it the status inherits the surrounding type, so set it inside a Heading or a stat value. */
  size?: "sm" | "md";
} & ({ icon: IconSource; loading?: boolean } | { icon?: IconSource; loading: true }) & {
    ref?: React.Ref<HTMLSpanElement>;
  }) {
  return (
    <span
      ref={ref}
      data-slot="status-text"
      data-tone={tone}
      data-size={size}
      data-loading={loading || undefined}
      className={cn(styles.status, className)}
      {...props}
    >
      {loading || !icon ? <Spinner /> : <Icon icon={icon} />}
      <span>{children}</span>
    </span>
  );
}
StatusText.displayName = "StatusText";

/**
 * Marks every case-insensitive occurrence of query in text as a search match. The query is literal
 * text, never a pattern; terms matches each whitespace-separated word on its own.
 */
export function Highlight({
  text,
  query,
  terms = false,
  className
}: {
  text: string;
  query?: string;
  terms?: boolean;
  className?: string;
}) {
  const needles = (terms ? (query ?? "").split(/\s+/) : [(query ?? "").trim() && (query ?? "")])
    .map((needle) => needle.toLowerCase())
    .filter(Boolean);
  const lower = text.toLowerCase();
  const ranges = needles
    .flatMap((needle) => {
      const found: [number, number][] = [];
      for (let at = lower.indexOf(needle); at >= 0; at = lower.indexOf(needle, at + 1))
        found.push([at, at + needle.length]);
      return found;
    })
    .sort((a, b) => a[0] - b[0])
    .reduce<[number, number][]>((merged, range) => {
      const last = merged.at(-1);
      if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
      else merged.push([...range]);
      return merged;
    }, []);
  if (!ranges.length || lower.length !== text.length) return text;
  const parts: React.ReactNode[] = [];
  let from = 0;
  ranges.forEach(([start, end]) => {
    if (start > from) parts.push(text.slice(from, start));
    parts.push(
      <mark key={start} data-slot="highlight" className={cn(styles.highlight, className)}>
        {text.slice(start, end)}
      </mark>
    );
    from = end;
  });
  if (from < text.length) parts.push(text.slice(from));
  return parts;
}

.truncate {
  display: inline-block;
  position: relative;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  vertical-align: bottom;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.measure {
  position: absolute;
  width: max-content;
  visibility: hidden;
  pointer-events: none;
  inset-inline-start: 0;
}
.collapse {
  display: block;
}
.collapse[hidden] {
  display: none;
}
.collapseInner {
  min-height: 0;
}
.text {
  margin: 0;
  color: var(--cipher-ink, var(--foreground));
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.small {
  margin: 0;
  color: var(--cipher-text2, var(--muted-foreground));
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.muted {
  color: var(--cipher-muted, var(--muted-foreground));
}
.preWrap {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.measurePage {
  width: 100%;
  max-width: var(--cipher-size-measure-page);
  margin-inline: auto;
  padding: var(--cipher-space-content-section) var(--cipher-space-40);
}
.measureForm {
  width: 100%;
  max-width: var(--cipher-size-measure-form);
}
@media (max-width: 640px) {
  .measurePage {
    padding: var(--cipher-space-20) var(--cipher-space-16);
  }
}
.stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.inline {
  display: flex;
  min-width: 0;
}
.grid {
  display: grid;
  min-width: 0;
}
.stack > *,
.inline > *,
.grid > * {
  min-width: 0;
}
.gridSplit {
  container-type: inline-size;
}
.gridSplit > * {
  grid-column: 1 / -1;
}
/* Container conditions cannot read custom properties, so this repeats size-sidecar-collapse (896px), the two-column breakpoint DetailLayout uses. */
@container (min-width: 896px) {
  .gridSplit > * {
    grid-column: auto;
  }
}
.container {
  width: 100%;
  min-width: 0;
  margin-inline: auto;
  max-width: var(--cipher-size-measure-page);
}
.measureProse {
  width: 100%;
  min-width: 0;
  max-width: var(--cipher-size-measure-prose);
}
.heading {
  margin: 0;
  color: var(--cipher-ink, var(--foreground));
  font-family: var(--cipher-heading-family);
  font-size: var(--cipher-heading-size);
  line-height: var(--cipher-heading-line);
  font-weight: var(--cipher-heading-weight);
  letter-spacing: var(--cipher-heading-tracking);
  overflow-wrap: anywhere;
  text-wrap: balance;
}
.heading[data-size="page"] {
  --cipher-heading-family: var(--cipher-type-title-lg-font-family);
  --cipher-heading-size: var(--cipher-type-title-lg-font-size);
  --cipher-heading-line: var(--cipher-type-title-lg-line-height);
  --cipher-heading-weight: var(--cipher-type-title-lg-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-lg-letter-spacing);
}
.heading[data-size="display"] {
  --cipher-heading-family: var(--cipher-type-display-font-family);
  --cipher-heading-size: var(--cipher-type-display-font-size);
  --cipher-heading-line: var(--cipher-type-display-line-height);
  --cipher-heading-weight: var(--cipher-type-display-font-weight);
  --cipher-heading-tracking: var(--cipher-type-display-letter-spacing);
}
.heading[data-size="section"] {
  --cipher-heading-family: var(--cipher-type-title-font-family);
  --cipher-heading-size: var(--cipher-type-title-font-size);
  --cipher-heading-line: var(--cipher-type-title-line-height);
  --cipher-heading-weight: var(--cipher-type-title-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-letter-spacing);
}
.heading[data-size="subsection"] {
  --cipher-heading-family: var(--cipher-type-title-sm-font-family);
  --cipher-heading-size: var(--cipher-type-title-sm-font-size);
  --cipher-heading-line: var(--cipher-type-title-sm-line-height);
  --cipher-heading-weight: var(--cipher-type-title-sm-font-weight);
  --cipher-heading-tracking: var(--cipher-type-title-sm-letter-spacing);
}
.meta {
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
  font-variant-numeric: tabular-nums;
  color: var(--cipher-muted, var(--muted-foreground));
}
.meta.mono {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
}
.status {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  vertical-align: top;
  color: var(--cipher-text2, var(--muted-foreground));
}
.status > svg {
  flex: none;
  width: var(--cipher-size-icon);
  height: var(--cipher-size-icon);
  stroke-width: var(--cipher-stroke-icon);
}
.status[data-size="sm"] {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.status[data-size="sm"] > svg {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
}
.status[data-size="md"] {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
.status[data-tone="ok"] {
  color: var(--cipher-ok);
}
.status[data-tone="warn"] {
  color: var(--cipher-warn);
}
.status[data-tone="bad"] {
  color: var(--cipher-bad);
}
.highlight {
  background-color: var(--cipher-accent);
  color: var(--cipher-on-accent);
}
